let modal = JdModalViewController(size: .md, persistent: false)
modal.contentView.addSubview(body)
modal.onRequestClose = { reason in    // 웹 jd-request-close 등가
    reason != .backdrop               // false 반환 시 닫기 중단
}
modal.onClose = { print("닫힘") }
modal.present(from: self)

modal.requestClose(.close)            // 코드로 닫기 요청
